Here's a complete, runnable example demonstrating the three common `useEffect` patterns:

```jsx
// App.jsx — React 18+
import { useState, useEffect } from "react";

export default function App() {
  const [count, setCount] = useState(0);
  const [seconds, setSeconds] = useState(0);

  // 1. No dependency array: runs after EVERY render
  useEffect(() => {
    console.log("rendered; count =", count);
  });

  // 2. Empty array: runs once after mount, cleanup on unmount
  useEffect(() => {
    const id = setInterval(() => setSeconds((s) => s + 1), 1000);
    return () => clearInterval(id); // cleanup prevents the leak
  }, []);

  // 3. Dependency array: runs when `count` changes
  useEffect(() => {
    document.title = `Count: ${count}`;
  }, [count]);

  return (
    <div>
      <h1>Count: {count}</h1>
      <button onClick={() => setCount((c) => c + 1)}>Increment</button>
      <p>Timer: {seconds}s</p>
    </div>
  );
}
```

Key points:
- **Cleanup** (`return () => clearInterval(id)`) runs before the effect re-runs and on unmount.
- Dependencies must include every reactive value the effect reads, or you get stale values.
- If you're on React 19 and the effect is only fetching data, prefer a data-fetching library or `use()` — `useEffect` fetching has no built-in race-condition handling.

